'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const poses=['坐姿调息','颈侧伸展','十指交扣上伸','坐姿侧伸展','坐姿扭转','束角前屈','单腿前屈','跪姿支撑侧伸','牛式','猫式','平板支撑','俯卧伸展','下犬式','低弓步','弓步单臂上伸','高弓步合十','弓步合十扭转','分腿前屈','婴儿式','跪姿侧伸示意','穿针引线示意','跪坐调息','跪坐双臂上举','合十收束'];
let state={title:'我的瑜伽练习',source:'',artworkVersion:2,demo:false,items:[],selected:0}, page='import',mode='link',pending='',toastTimer;
try{const d=JSON.parse(localStorage.getItem('yoga-sequence-v1'));if(d&&Array.isArray(d.items)&&d.items.length<=150)state={...state,...d,artworkVersion:d.artworkVersion||1};}catch{}
function save(){try{localStorage.setItem('yoga-sequence-v1',JSON.stringify(state));$('#save-status').textContent='预览已保存在此浏览器';}catch{notify('浏览器无法保存，下次可重新打开示例。');}}
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
// Original artwork extracted from the user-approved v1 PDF, without redrawing.
function figure(kind=0){if(kind===null||!Number.isInteger(Number(kind))||!ORIGINAL_ARTWORK[Number(kind)])return '<svg width="150" height="140" viewBox="0 0 150 140" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="暂无原版插画"><text x="75" y="65" text-anchor="middle" font-size="10" fill="#7b8970">暂无原版插画</text><text x="75" y="82" text-anchor="middle" font-size="7" fill="#929b87">原版素材暂未覆盖</text></svg>';return `<svg width="150" height="140" viewBox="0 0 150 140" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(poses[Number(kind)])}原版插画"><image href="${ORIGINAL_ARTWORK[Number(kind)]}" x="0" y="0" width="150" height="140" preserveAspectRatio="xMidYMid meet"/></svg>`;}
function migrateArtwork(d){if(d.artworkVersion===2)return d;const mapping=[0,3,null,null,9,8,12,13,null,null,18,null];d.items=d.items.map(p=>({...p,kind:mapping[p.kind]??null,checked:false}));d.artworkVersion=2;return d;}
state=migrateArtwork(state);

function itemMarkup(p,i){return `<div class="pose-card"><span class="num">${String(i+1).padStart(2,'0')}</span>${figure(p.kind)}<b>${esc(p.name)}</b><small>${esc(p.side||'居中')} · ${esc(p.cue||'按熟悉的节奏')}</small></div>`;}
function strip(items,start=0,part=''){return `<div class="strip-title">${esc(state.demo?'晨间舒展 · 示例':state.title)}<small>${esc(part||'PRACTICE AT YOUR OWN PACE')}</small></div>${items.map((p,i)=>itemMarkup(p,i+start)).join('')}<p style="font-size:8px;text-align:center;color:#929b84">${state.demo?'界面示例 · 非真实课程':'已有练习 · 体式插画示意'}<br>瑜序 · 留一点时间给自己</p>`;}
function sample(){return [0,3,9,12,13,18].map((kind,i)=>({id:crypto.randomUUID(),kind,name:poses[kind],side:i===1?'左侧':i===4?'右腿在前':'居中',cue:'按熟悉的节奏',time:i*90,checked:false}));}
function heading(eyebrow,title,sub,badge='为自己，留一段练习时间'){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div><span class="pill">✧ ${badge}</span></div>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').innerHTML='工作室 <span>/</span> '+({import:'导入练习',export:'预览与打印'}[page]);$('#app').innerHTML=page==='import'?importView():exportView();bind();}
function importView(){const demo=sample();return heading('A LITTLE LESS SCREEN. A LITTLE MORE YOU.','把熟悉的练习，<em>留在垫边。</em>','导入练过的视频，预览并下载你的练习提示图。')+`<div class="workspace"><section class="panel"><h2>开启一份新的练习</h2><p class="sub">选择视频来源，或先看看贴纸的样子。</p><div class="tabbar"><button data-mode="link" class="${mode==='link'?'active':''}">粘贴视频链接</button><button data-mode="file" class="${mode==='file'?'active':''}">选择本地视频</button></div>${mode==='link'?`<label for="url">视频链接</label><input id="url" type="url" placeholder="粘贴 B 站或其他平台的课程链接"><div class="info">自动生成待接入。目前不会读取链接或生成体式图；可打开下方示例预览。</div><button class="secondary wide" id="submit-source">确认视频来源 ↗</button>`:`<div class="file-zone"><span>↥</span><p>选择你练过的瑜伽视频</p><small>仅选择本地文件，不上传</small><input id="file" type="file" accept="video/*"></div><div class="info">自动生成待接入。当前选择文件后不会分析视频或生成体式图。</div>`}${pending?`<p class="info" role="status">${esc(pending)}</p>`:''}<div class="or">先感受一下成品</div><button class="demo-btn" id="demo"><span class="thumb">${figure(0)}</span><span><strong>晨间舒展 · 示例练习</strong><small>6 个示意动作 · 可预览 · 可打印</small></span><span class="arr">↗</span></button>${state.items.length?'<button class="secondary wide" id="resume" style="margin-top:12px">查看上次的预览 →</button>':''}</section><section class="preview-panel"><div class="preview-head"><span>一眼，想起下一个动作</span><span>预览示意 ↙</span></div><div class="sample-wrap"><div class="paper-strip"><div class="strip-title">晨间舒展<small>01 — BEGIN WITH A BREATH</small></div>${demo.slice(0,3).map(itemMarkup).join('')}</div><div class="paper-strip"><div class="strip-title">慢慢，展开<small>02 — FIND YOUR OWN FLOW</small></div>${demo.slice(3).map((p,i)=>itemMarkup(p,i+3)).join('')}</div></div></section></div><div class="steps" style="grid-template-columns:repeat(2,1fr)"><div class="step"><span>01</span><div><strong>导入熟悉的练习</strong><p>提供视频链接，或选择本地视频</p></div></div><div class="step"><span>02</span><div><strong>预览，带回垫边</strong><p>下载长条图片，或 A4 分段打印</p></div></div>`;}
function exportView(){const chunks=[];for(let i=0;i<state.items.length;i+=5)chunks.push(state.items.slice(i,i+5));return heading('TAKE YOUR PRACTICE OFF SCREEN.','一条小小的提示，<em>陪你回到呼吸。</em>','查看分段排版，将这份练习带到瑜伽垫旁。',state.demo?'示例内容 · 仅供体验':'已有练习预览')+`<div class="export-grid"><section class="panel"><h2>打印与导出</h2><p class="sub">${state.items.length} 个动作 · ${chunks.length} 段</p><label>版式</label><p>A4 分段 · 每段 5 个动作<br><small class="hint">宽 6 cm，沿裁切线剪下后纵向连接</small></p><div class="info">${state.demo?'当前展示的是示例内容，不对应你导入的视频；插画沿用原版素材，仍有待精修的体式。':'已有练习预览。视频自动生成待接入。'}</div><button class="primary wide" id="print">打印 / 保存 PDF ↗</button><p class="hint">打印时选择 A4、100% 实际大小，关闭页眉页脚。每页最多放三段。</p><button class="secondary wide" id="png" style="margin-top:12px">下载完整长条 PNG</button><button class="secondary wide" id="svg" style="margin-top:12px">下载长条 SVG（内嵌原图）</button><button class="secondary wide" data-page="import" style="margin-top:24px">← 返回导入</button></section><div class="sheet-view">${chunks.length?chunks.map((c,i)=>`<div class="paper-strip">${strip(c,i*5,`第 ${i+1} / ${chunks.length} 段 · 从上向下练习`)}</div>`).join(''):'<div class="empty">打开示例，查看贴纸预览。</div>'}</div></div>`;}
function safeURL(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function navigate(p){if(!['import','export'].includes(p))return;if(p==='export'&&!state.items.length){notify('请先打开示例练习，查看预览与打印。');return;}page=p;render();window.scrollTo(0,0);}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;pending='';render();});const on=(id,fn)=>{const el=$('#'+id);if(el)el.onclick=fn;};
on('demo',()=>{state={title:'晨间舒展 · 示例练习',source:'',artworkVersion:2,demo:true,items:sample(),selected:0};save();navigate('export');});on('resume',()=>navigate('export'));
on('submit-source',()=>{const source=$('#url').value.trim();if(!source||safeURL(source)==='#'){notify('请输入有效的 http 或 https 视频链接。');return;}pending='已填写视频来源。自动生成待接入，尚未开始处理。';notify(pending);const note=document.createElement('p');note.className='info';note.setAttribute('role','status');note.textContent=pending;$('#submit-source').parentNode.querySelector('[role="status"]')?.remove();$('#submit-source').after(note);});
if($('#file'))$('#file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('video/')){notify('请选择视频文件。');return;}pending='已选择：'+f.name+'。自动生成待接入，文件未上传。';render();};
on('print',printSheet);on('svg',()=>download(longSVG(),'瑜序-完整长条.svg','image/svg+xml'));on('png',exportPNG);
}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function printSheet(){if(!state.items.length)return;document.querySelector('.print-only')?.remove();const root=document.createElement('div');root.className='print-only';let html='';for(let base=0;base<state.items.length;base+=15){html+='<div class="print-page">';for(let i=base;i<Math.min(base+15,state.items.length);i+=5)html+=`<section class="print-strip">${strip(state.items.slice(i,i+5),i,`第 ${Math.floor(i/5)+1} 段 · 宽 6 cm`)}</section>`;html+='</div>';}root.innerHTML=html;document.body.append(root);window.print();}
function longSVG(){const height=150+state.items.length*210;return `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="${height}" viewBox="0 0 300 ${height/2}"><rect width="300" height="100%" fill="#fffdf5"/><text x="150" y="28" text-anchor="middle" font-family="sans-serif" font-size="14" fill="#435a3b">${esc(state.title).slice(0,45)}</text><text x="150" y="49" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#818c74">${state.demo?'界面示例 · 非真实课程 · 插画尚未核验':'已有练习 · 体式插画示意'}</text>${state.items.map((p,i)=>`<g transform="translate(0 ${60+i*105})"><line x1="20" y1="0" x2="280" y2="0" stroke="#dfe5d5" stroke-dasharray="3 3"/><text x="24" y="18" font-size="9" fill="#94a282">${i+1}</text><g transform="translate(100 0) scale(.55)">${figure(p.kind)}</g><text x="150" y="85" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#435a3b">${esc(p.name)} · ${esc(p.side)}</text><text x="150" y="99" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#818c74">${esc(p.cue)}</text></g>`).join('')}</svg>`;}
async function exportPNG(){const raw=longSVG(),url=URL.createObjectURL(new Blob([raw],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});const canvas=document.createElement('canvas');canvas.width=600;canvas.height=150+state.items.length*210;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();download(blob,'瑜序-完整长条.png');notify('长条图片已导出。');}catch{notify('图片导出失败，可先使用 SVG 下载或打印。');}finally{URL.revokeObjectURL(url);}}
$('#about').onclick=()=>$('#modal').showModal();$('#close-modal').onclick=()=>$('#modal').close();$('.brand').onclick=e=>{e.preventDefault();navigate('import');};render();
